describe('Change Billing Address During Checkout', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should successfully change billing address during checkout', () => {
    // Verify initial billing address is displayed
    cy.get('[data-testid="billing-address-display"]').should('be.visible');
    cy.get('[data-testid="billing-address-display"]').should('contain', '123 Main St');

    // Click on change billing address button
    cy.get('[data-testid="change-billing-address-btn"]').click();

    // Verify address form appears
    cy.get('[data-testid="billing-address-form"]').should('be.visible');
    cy.get('[data-testid="billing-address-form"]').should('contain', 'Change Billing Address');

    // Fill in new billing address
    cy.get('[data-testid="new-address-line1"]').type('456 Oak Ave');
    cy.get('[data-testid="new-address-line2"]').type('Apt 2');
    cy.get('[data-testid="new-city"]').type('Springfield');
    cy.get('[data-testid="new-state-select"]').select('IL');
    cy.get('[data-testid="new-zipcode"]').type('62701');

    // Click save button
    cy.get('[data-testid="save-billing-address-btn"]').click();

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Billing address updated successfully');

    // Verify new address is displayed
    cy.get('[data-testid="billing-address-display"]').should('contain', '456 Oak Ave');
    cy.get('[data-testid="billing-address-display"]').should('contain', 'Springfield, IL 62701');

    // Verify checkout continues
    cy.get('[data-testid="continue-to-payment-btn"]').should('be.visible');
    cy.get('[data-testid="continue-to-payment-btn"]').click();
  });

  it('should display error when billing address is not fully filled', () => {
    // Click on change billing address button
    cy.get('[data-testid="change-billing-address-btn"]').click();

    // Fill in only partial address
    cy.get('[data-testid="new-address-line1"]').type('700 Pine Ln');
    cy.get('[data-testid="new-city"]').type('Shelbyville');
    cy.get('[data-testid="new-state-select"]').select('KY');
    // Zip code is left empty

    // Attempt to save without zip code
    cy.get('[data-testid="save-billing-address-btn"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Zip code is required');

    // Verify address form is still visible
    cy.get('[data-testid="billing-address-form"]').should('be.visible');

    // Verify billing address did not change
    cy.get('[data-testid="billing-address-display"]').should('contain', '123 Main St');

    // Verify user can correct the error
    cy.get('[data-testid="new-zipcode"]').type('42001');
    cy.get('[data-testid="save-billing-address-btn"]').click();

    // Verify success message appears after correction
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Billing address updated successfully');
  });
});
